	  \Pc{{\mathcal{E}}}{\mathbb R(t) = G, {\mathcal{F}}_{e,f}} = \frac{\Pc{{\mathcal{E}}\cap {\mathcal{F}}_{e,f}}{\mathbb R(t) = G}}{\Pc{{\mathcal{F}}_{e,f}}{\mathbb R(t) = G}} \le \frac{\Pc{{\mathcal{E}}}{\mathbb R(t) = G}}{\Pc{{\mathcal{F}}_{e,f}}{\mathbb R(t) = G}} \le 2 e^{ - \lambda(t)}.
	\end{equation*}

\begin{equation*}
  {\mathcal{E}} :=  \bigcup_{i \in [2]} \left\{ \max_{u,v \in V_i, u \neq v}\left|\frac{\theta_{G,\mathbb R}(u,v)}{\tau qd_i } - 1\right| > \delta(t) \right\} \quad\text{and}\quad {\mathcal{F}}_{e,f} := \{ e\in \mathbb R, f \notin \mathbb R \}.
\end{equation*}

\begin{equation}
  \label{eq_typical2}
  \Pc{\max_{i \in [2] : u_i \neq v_i}\left|\frac{\theta_{G,\mathbb R}(u_i,v_i)}{\tau qd_i } - 1\right| > \delta(t) }{\mathbb R(t) = G, e \in \mathbb R, f \notin \mathbb R} \le \tau^2 \delta(t).
\end{equation}

\begin{equation*}
	  \Pc{{\mathcal{E}}}{\mathbb R(t) = G, {\mathcal{F}}_{e,f}} = \frac{\Pc{{\mathcal{E}}\cap {\mathcal{F}}_{e,f}}{\mathbb R(t) = G}}{\Pc{{\mathcal{F}}_{e,f}}{\mathbb R(t) = G}} \le \frac{\Pc{{\mathcal{E}}}{\mathbb R(t) = G}}{\Pc{{\mathcal{F}}_{e,f}}{\mathbb R(t) = G}} \le 2 e^{ - \lambda(t)}.
	\end{equation*}

\label{sec_degs_codegs}
In this section we prove facts about the neighborhood structure of $\mathbb R(t)$, one of which will be enough to deduce Lemma~\ref{lem_thetas}, while the other two will be used in the proof of Lemma~\ref{lem_ef} in Section~\ref{sec_quasi}. We start, in Subsection~\ref{ss_codegs}, with  a tail bound for the co-degrees in $\mathbb R = \mathbb R(n_1,n_2,p)$ (Lemma~\ref{lem_codegs}). In Subsection~\ref{ss_Rt_cod} we analyze the process~$(\mathbb R(t))_t$. First, we show that the vertex degrees in the process grow proportionally until almost the very end (Lemma~\ref{lem_degrees}). Then, conditioning on $\mathbb R$ having concentrated co-degrees, we  prove that the co-degrees in $\mathbb R(t)$ do not exceed  their expectation too much (Lemma~\ref{lem_codegsRt}).
Finally, in Subsection~\ref{ss_proof_thetas}, we present a proof of Lemma~\ref{lem_thetas} based on Lemma~\ref{lem_codegs}.

We define the \emph{co-degree} of two distinct vertices $u, v$ as
\begin{equation}
\label{eq_def_cod}
 \operatorname{cod}_F(u,v) := |\Gamma_F(u) \cap \Gamma_F(v)|.

  \label{lem_codegs}
	Suppose that $\hat p\hat n  \to \infty$  and let $\lambda = \lambda(n_1,n_2)$ be such that $\lambda \to \infty$.
	Then, for any distinct $u_1, v_1 \in V_1$,
\begin{equation*}
  \prob{
	|\operatorname{cod}_{\mathbb R}(u_1,v_1) - p^2n_{2}| > 20\left( \hat p^3n_{2}\mathbb I + \frac{\hat pn_{2}}{\hat n} + \sqrt{\lambda \hat p^2 n_2} \right) + \lambda
      } = O\left( \sqrt N e^{ - \lambda } \right),
\end{equation*}
where $\mathbb I$ is defined in~\eqref{eq_defI}.

\begin{equation*}
  \prob{
	|\operatorname{cod}_{\mathbb R}(u_1,v_1) - p^2n_{2}| > 20\left( \hat p^3n_{2}\mathbb I + \frac{\hat pn_{2}}{\hat n} + \sqrt{\lambda \hat p^2 n_2} \right) + \lambda
      } = O\left( \sqrt N e^{ - \lambda } \right),
\end{equation*}

We first claim that it is sufficient to assume $p \le 1/2$ and prove
that for any distinct $u_1, v_1 \in V_1$
\begin{equation}
  \label{eq_codegconcnoq}
  \prob{ |\operatorname{cod}_{\mathbb R}(u_1,v_1) - p^2n_2| > 20\left(p^3n_2\mathbb I + \frac{pn_2}{\hat n} + \sqrt{\lambda p^2n_2 } \right) + \lambda } = O\left( \sqrt N e^{ - \lambda } \right).
\end{equation}
	To see this, note that by~\eqref{eq_coco}, recalling $q = 1 - p$,
	\begin{equation*}
		\operatorname{cod}_{\mathbb R}(u_1, v_1) - p^2n_2= 2pn_2 - (n_2 - \operatorname{cod}_{K \setminus \mathbb R}(u_1,v_1))- p^2n_2=\operatorname{cod}_{K \setminus \mathbb R}(u_1,v_1) - q^2n_2.
	\end{equation*}
	Further, $K \setminus \mathbb R = K \setminus \mathbb R(n_1,n_2,p)$ has the same distribution as $\mathbb R(n_1,n_2,q)$. So, if $p > 1/2$, the lemma follows by applying~\eqref{eq_codegconcnoq} with $q$ instead of $p$.


	The crude proof idea comes from our anticipation that $\operatorname{cod}_{\mathbb R}(u_1,v_1)$ behaves similarly to $\operatorname{cod}_{\mathbb G(n_1,n_2,p)}(u_1,v_1)$, which is distributed as $\operatorname{Bin}(n_2, p^2)$ or, approximately, as $\operatorname{Po}(p^2n_2)$. We will show that each tail of $\operatorname{cod}_{\mathbb R}(u_1,u_2)$ is comparable to the tail of $\operatorname{Po}(\mu)$ with expectation~$\mu$ fairly close to $p^2n_2$ and then apply the Chernoff bounds (this is packaged in Claim~\ref{clm_Poiss_bounds} below). Further we consider the cases $\mathbb I = 1$ and $\mathbb I = 0$ and apply Claim~\ref{clm_Poiss_bounds} analogously to the proof of Theorem 2.1 in~\cite{KSVW}: in the case $\mathbb I = 1$ we use switchings and in the case $\mathbb I = 0$ we use asymptotic enumeration (Theorem~\ref{thm_enum}).

	Fix distinct $u_1, v_1 \in V_1$ and set $X(u_1,v_1): = \operatorname{cod}_{\mathbb R}(u_1,v_1)$. Further, recall that ${\mathcal{R}}(n_1,n_2,p)$ is the class of subgraphs of $K_{n_1,n_2}$ such that every $v \in V_i$ has degree $d_i$, for $i = 1, 2$, and let
	\[
	  {\mathcal{R}}_k(u_1,v_1) = \{H \in {\mathcal{R}}(n_1,n_2,p) : \operatorname{cod}_H(u_1,v_1) = k \}, \qquad k = 0, \dots, d_1.
	  \]
	\begin{claim}
	  \label{clm_Poiss_bounds}
	 Fix two vertices $u_1,v_1\in V_1$. Suppose that positive numbers $r_k, k = 0, \dots, d_1,$ are such that
	  \begin{equation*}
	    |{\mathcal{R}}_k(u_1,v_1)| \sim r_k, \text{ uniformly in $k$ as } (n_1, n_2) \to \infty,
	  \end{equation*}
	  and there exist numbers $0 \le \mu_- \le \mu_+ \le N$ such that
	  \begin{equation*}
	    \frac{r_k}{r_{k-1}} \le \frac{\mu_+}{k}, \text{ for } k \in [\mu_+, d_1]
	    \quad \text{ and } \quad
	    \frac{r_{k-1}}{r_k} \le \frac{k}{\mu_-}, \text{ for } k \in [1, \mu_-].
	  \end{equation*}
	  If $x \ge \sqrt{2\mu_+ \lambda} + \lambda$, then
	  \begin{equation}
	    \label{eq_twotailbound}
	    \prob{X(u_1,v_1) \ge \mu_+ + x} + \prob{X(u_1,v_1) \le \mu_- - x} = O(\sqrt{N} e^{-\lambda}).
	  \end{equation}
	\end{claim}
	\begin{proof}
	  Note that if $Z_+ \sim \operatorname{Po}(\mu_+)$, then $\mu_+/k = \prob{Z_+ = k}/\prob{Z_+ = k - 1}$. Setting $m = \lfloor \mu_+ \rfloor$,
	  for any integer $i\in\{m,\dots,d_1\}$, and abbreviating $X:=X(u_1,v_1)$ and ${\mathcal{R}}_j:={\mathcal{R}}_j(u_1,v_1)$, we have
	  \begin{align*}
	    \prob{X \ge i}  &= \frac{\sum_{j \ge i}|{\mathcal{R}}_j| }{|{\mathcal{R}}(n_1,n_2,p)|}\le \sum_{j \ge i} \frac{|{\mathcal{R}}_j|}{|{\mathcal{R}}_{m}|} \sim \sum_{j \ge i} \frac{r_j}{r_m} = \sum_{j \ge i} \prod_{k = m + 1}^{j} \frac{r_k}{r_{k-1}} \le \sum_{j \ge i} \prod_{k = m + 1}^{j} \frac{\mu_+}{k}\\
	    &= \sum_{j \ge i} \prod_{k = m + 1}^{j}\frac{\prob{Z_+ = k}}{\prob{Z_+ = k-1}}  = \sum_{j \ge i} \frac{\prob{Z_+ = j}}{\prob{Z_+ = m}} = \frac{\prob{Z_+ \ge i}}{\prob{Z_+ = m}}.
	  \end{align*}
	  Since  $\mu_+ \le N$, by \eqref{eq_largestatom} we have $\prob{Z_+ = m} = \Omega(1/\sqrt{\mu_+}) = \Omega(1/\sqrt{N})$, and conclude that
	  \begin{equation}
	    \label{eq_Poisstail_up}
	    \prob{X \ge i} = O\left( \sqrt{N} \cdot \prob{Z_+ \ge i} \right), \qquad i \ge \mu_+.
	  \end{equation}
	  Similarly, if $Z_- \sim \operatorname{Po}(\mu_-)$, then for $i\le m := \lfloor \mu_- \rfloor$, using $k/\mu_- = \prob{Z_- = k-1}/\prob{Z_- = k}$,
	  \begin{equation*}
	    \prob{X \le i}\le \sum_{j \le i} \frac{|{\mathcal{R}}_j|}{|{\mathcal{R}}_{m}|} \sim \sum_{j \le i}\prod_{k = j + 1}^{ m} \frac{r_{k-1}}{r_{k}} \le \sum_{j \le i}\prod_{k = j + 1}^{ m} \frac{\prob{Z_- = k-1}}{\prob{Z_- = k}} = \frac{\prob{Z_- \le i}}{\prob{Z_- = m}},
	  \end{equation*}
	  and therefore, again using \eqref{eq_largestatom},
	  \begin{equation}
	    \label{eq_Poisstail_down}
	    \prob{X \le i} = O\left( \sqrt{N} \cdot \prob{Z_- \le i} \right), \qquad i \le \mu_-.
	  \end{equation}
	  Since the RHS{} of \eqref{eq_twotailbound} does not depend on $x$, we can assume the equality: $x = \sqrt{2\mu_+\lambda} + \lambda$. Inequalities \eqref{eq_hypergeomUpTailExp} and $\eqref{eq_hypergeomLowTailExp}$ imply
	  \begin{equation*}
	    \begin{split}
	      \prob{Z_+ \ge \mu_+ + x} &+ \prob{Z_- \le \mu_- - x} \le \exp \left( - \frac{x^2}{2(\mu_+ + x/3)} \right) + \exp \left( -\frac{x^2}{2\mu_-} \right) \\
	      \justify{$\mu_- \le \mu_+, x > 0$} &\le 2 \exp \left( -\frac{x^2}{2(\mu_+ + x/3)} \right) \\
	      \justify{$x = \sqrt{2 \mu_+ \lambda} + \lambda$} &= 2 \exp \left( -\frac{\lambda(2\mu_+ + 2\sqrt{2\mu_+ \lambda} + \lambda)}{2\mu_+ + \sqrt{2\mu_+ \lambda}/3 + \lambda/3} \right) \le 2e^{-\lambda}.
	    \end{split}
	  \end{equation*}
	  Combining this with \eqref{eq_Poisstail_up} and \eqref{eq_Poisstail_down} yields \eqref{eq_twotailbound}.
	\end{proof}

	It remains to prove \eqref{eq_codegconcnoq}. We consider separately the cases $\mathbb I = 1$ and $\mathbb I = 0$.

\smallskip

	\textbf{Case $\mathbb I = 1$.}
	If $p \ge 1/5$, then deterministically
	$\operatorname{cod}_{\mathbb R}(u_1,u_2) \le pn_2\le 5p^2n_2 \le p^2 n_2 + 20 p^3 n_2$ and $\operatorname{cod}_{\mathbb R}(u_1, u_2) - p^2 n_2 \ge - p^2 n_2 \ge -5p^3 n_2$, and hence \eqref{eq_codegconcnoq} holds trivially. So we further assume $p < 1/5$.


