\end{align*}
Hence, to prove \eqref{enough}, it suffices to show that, for any $ y = 0, \dots, y_0$,
\begin{equation}
	\label{enougher}
\PcH{{\mathcal{E}}_\eqref{enough}}{Y = y} \le e^{-\lambda/3}.
\end{equation}
Fix an integer $y \in [0, y_0]$ and a set $S\subseteq V_2$ of size $|S| = y \le y_0$. Under an additional condi\-tioning $\Gamma_{\mathbb R(t)}(u_1)\cap \Gamma_H(v_1) = S$, set $\mathbb R(t)$ is the union of a fixed $y$-element set $\{u_1w : w \in S\}$ and a random $(t - y)$-element subset of $E(H) \setminus \{u_1w : w \in \Gamma_H(u_1)\cap \Gamma_H(v_1)\}$.
Thus, in this conditional space, $X := \operatorname{cod}_{\mathbb R(t)}(u_1,v_1)$ counts how many of these $t-y$ random edges fall into the set $\{v_1w : w \in S\}$ and therefore $X \sim \operatorname{Hyp}(M - \operatorname{cod}_H, y, t - y)$. Moreover, the distribution of $X$ is the same for all $S$ of size $y$, so $X$ has the same distribution when conditioned on $Y = y$. In particular,
	\begin{align*}
	  \mu_X := \EcH{X}{Y = y} &= \frac{y(t-y)}{M-\operatorname{cod}_H} \\
	  \justify{$y \ge 0$} &\le \frac{yt}{M} \left(1 + \frac{\operatorname{cod}_H}{M - \operatorname{cod}_H}\right) \\
	  \justify{$M = pn_1n_2, \operatorname{cod}_H \le pn_2$} &\le (1-\tau) y \left(1 + \frac{1}{n_1 - 1}\right) \\
		\justify{$y \le y_0$ and \eqref{eq_Y}}	&\le (1-\tau)^2p^2n_2 + 20q^3n_2 \mathbb I + 13 \sqrt{\lambda n_2} + \frac{n_2}{n_1 - 1}.
		\\
	\justify{$n_1 \ge n_2$}	&\le (1-\tau)^2p^2n_2 + 20q^3n_2 \mathbb I + 14 \sqrt{\lambda n_2}.
	\end{align*}
	Using again \eqref{eq_hypergeomUpTailExp} as well as inequalities $\mu_X \le n_2$ and $\lambda \le n_2$, we infer that
	 \begin{align*}
\PcH{X \ge \mu_X + \sqrt{\lambda n_2}}{Y = y}  \le \exp\left\{-\frac{\lambda n_2}{2(\mu_X + \sqrt{\lambda n_2}/3)}\right\} \le e^{-\lambda/3} ,
\end{align*}
which, together with the above upper bound on $\mu_X$, implies \eqref{enougher}. This completes the proof of Lemma~\ref{lem_codegsRt}.

