We say that a blue-red graph $F$ is \emph{$(r,b,\delta)$-regular}, if
\begin{equation}
  \label{eq_delta_regular}
	b - \delta \le d_{B} (v) \le b + \delta, \quad\text{and}\quad r - \delta \le d_{R} (v) \le r + \delta \quad \text{ for every } v\in V_1\cup V_2.

\begin{equation}
  \label{eq_delta_regular}
	b - \delta \le d_{B} (v) \le b + \delta, \quad\text{and}\quad r - \delta \le d_{R} (v) \le r + \delta \quad \text{ for every } v\in V_1\cup V_2.
\end{equation}

	\label{lem_ananas_prep}
	Let $r, b \in (0,1)$ be real numbers and define $\alpha := \min \{r,b\}$.
	Let $\nu<\alpha/16$ and $\delta \leq \alpha/16$ be positive reals and
	let $F \subseteq K$ be a $(r, b, \delta)$-regular, $(b + r, \delta)$-jumbled bipartite blue-red graph. If sets $X \subseteq V_i$, $Y \subseteq V_{3-i}$ satisfy
\begin{equation}
  \label{eq_small_cross}
	\varepsilon_{B}(X,\overline{Y}) + \varepsilon_{R}(\overline{X},Y) \le \nu,
\end{equation}
and
\begin{equation}
  \label{eq_less_one}
	\min \{b\rs{X},r\rs{Y}\} \leq \frac{rb}{r + b},
\end{equation}
then
\begin{equation}
	\label{eq_one_smaller}
	\max \{b\rs{X}, r\rs{Y}\} \le \frac{\nu}{1 - 7\delta/\alpha}.
\end{equation}

Since
\[
  \varepsilon_{R}(X,Y) = \frac{e_R(X,Y)}{n_1n_2} = \frac{\sum_{v\in X}e_R(\left\{ v \right\}, Y)}{n_1n_2} = \frac1{n_1}\sum_{v\in X}d_R(v,Y),
\]
from \eqref{eq_delta_regular} we have
\begin{equation}
  \label{eq_birblue2}
\varepsilon_{R}(X,Y) + \varepsilon_{R}(X,\overline{Y}) \leq (r + \delta)\rs{X}
\end{equation}
and, similarly,
\begin{equation}
  \label{eq_birred2}
	\varepsilon_{B}(X,Y) + \varepsilon_{B}(\overline{X},Y) \leq (b + \delta)\rs{Y}.
\end{equation}
By summing~\eqref{eq_small_cross},~\eqref{eq_birblue2} and~\eqref{eq_birred2}, we infer that
\begin{equation}
  \label{eq_ebr_upper}
  \varepsilon_F(X,Y) + \varepsilon_F(X,\overline{Y}) + \varepsilon_F(\overline{X},Y)\leq \nu + (r + \delta)\rs{X}  + (b + \delta)\rs{Y}.
  \end{equation}
On the other hand, by \eqref{eq_delta_regular},
\begin{equation*}
	\varepsilon_F(X,\overline{Y}) = \varepsilon_F(X, V_2) - \varepsilon_F(X,Y)
		\ge (b + r - 2\delta)\rs{X} - \varepsilon_F(X,Y)
\end{equation*}
and
\begin{equation*}
	\varepsilon_F(\overline{X},Y) = \varepsilon_F(V_1, Y) - \varepsilon_F(X,Y)
		\ge (b + r - 2\delta)\rs{Y} - \varepsilon_F(X,Y). 		
\end{equation*}
Hence, by \eqref{eq_quasi_rel} with $\pi = b + r$,
\begin{multline*}
	\varepsilon_F(X,Y) + \varepsilon_F(X,\overline{Y}) + \varepsilon_F(\overline{X},Y)
		\geq (b + r - 2\delta) (\rs{X} + \rs{Y}) - \varepsilon_F(X, Y) \\
	\ge (b + r  - 2\delta) (\rs{X} + \rs{Y}) - (b + r)\rs{X}\rs{Y} - \delta \sqrt{\rs{X}\rs{Y}}.
 \end{multline*}
 Comparing with \eqref{eq_ebr_upper}, we obtain the inequality
\begin{equation*}
	b \rs{X} + r \rs{Y} - \frac{(b + r)b\rs{X} r\rs{Y}}{br}
	\le \nu + \delta\left(3\rs{X} + 3\rs{Y} + \sqrt{\rs{X}\rs{Y}}\right).\\
\end{equation*}
Denoting $x := b\rs{X}$ and $y := r\rs{Y}$ and $h := rb/(b + r)$, this becomes
\begin{equation}
  \label{eq_quadratic}
	x +  y - \frac{x  y}h \le \nu + \delta \left( \frac{3x}b + \frac{3y}r +\sqrt{\frac{xy}{br}} \right) =: \psi.
\end{equation}
Trivially, by the definitions of $s(X)$ and $\alpha$, and by our assumptions on $\nu$ and $\delta$, we have
 \[
	 \psi \le \nu + 7\delta < \frac12\alpha\le \frac{1}{1/b + 1/r} = h.
 \]
Since our goal --- inequality \eqref{eq_one_smaller} --- now reads as
\[
	\max \left\{ x, y \right\} \le \frac{\nu}{1 - 7\delta /\alpha},
\]to complete the proof it is enough to assume, without loss of generality, that $\max \{x, y\} = y$ and show, equivalently, that
\begin{equation}
	y \le \nu + 7\delta y/\alpha.
	\label{eq_ybound}
\end{equation}
By \eqref{eq_less_one} we have $x = \min\{x,y\} \le h$. Note that $x = h$ cannot hold, since then the LHS{} of \eqref{eq_quadratic} would equal $h$, contradicting the fact that $\psi < h$.
Hence, we have $x < h$, which, together with $\psi < h$ and \eqref{eq_quadratic}, implies that
\begin{align*}
  y &\le \frac{\psi - x}{1 - x/h} = h - \frac{h - \psi}{1 - x/h} \le h - (h - \psi) = \psi = \nu + \delta \left( \frac{3x}b + \frac{3y}r + \sqrt{\frac{xy}{br}} \right) \le \nu + \frac{7\delta y}{\alpha},	
\end{align*}
and \eqref{eq_ybound} is proved.

\begin{align*}
  y &\le \frac{\psi - x}{1 - x/h} = h - \frac{h - \psi}{1 - x/h} \le h - (h - \psi) = \psi = \nu + \delta \left( \frac{3x}b + \frac{3y}r + \sqrt{\frac{xy}{br}} \right) \le \nu + \frac{7\delta y}{\alpha},	
\end{align*}

  \label{lem_walks}
